          `${promptText("\u56FA\u5B9A commit", "Pinned fixed commit")}: ${repository.reference.owner}/${repository.reference.repo}@${repository.reference.commitSHA}`,
          `${promptText("\u7528\u6237\u6307\u4EE4", "User instruction")}: ${taskInstruction}`
