      throw new Error("AI \u6CA1\u6709\u63D0\u4EA4\u901A\u8FC7\u516B\u7C7B\u7EC6\u8282\u95E8\u69DB\u7684\u7F51\u7EDC\u56FE\uFF1B\u5F53\u524D\u56FE\u672A\u88AB\u8986\u76D6\u3002");
